mapper.select:
select * (select case when tfpdl.TRADE_STATUS = '01' then '01' else '03' end validStatus, tfpdl.TOTLE_TRADE_ID busiCode, tfpdl.TG_BUSI_TYPE paBussType, fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_NAME finprodMarketName, fp.VDATE vDateWhole, fp.MDATE mDateWhole, nvl(tfpdl.SHARE_AMT/10000,0) repNomCapi, fpd.REF_ENTITY refEntity, tfpdl.TG_BUSI_TYPE creditEvent, tfpdl.CREDIT_EVENT_HAPPENED_DATE creditEventHappenedDate, tfpdl.CREDIT_EVENT_RESOLVE_DATE creditEventResolveDate, tfpdl.SETTLE_METHOD settleMethod, tfpdl.DELIVER_BOND deliverBond, tfpdl.TRADE_DATE deliverDate from TRD_FIN_PRODUCT_DEAL_TOTAL tfpdl left join FIN_PRODUCT fp on fp.FINPROD_ID = tfpdl.FINPROD_ID left join FIN_PRODUCT_ADD fpd on fpd.FINPROD_ID = tfpdl.FINPROD_ID where tfpdl.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F36} and tfpdl.IS_CANCEL = #{YES_OR_NO_N} and tfpdl.P_TOTLE_TRADE_ID is null
and tfpdl.TOTLE_TRADE_ID IN
#{busiCode,jdbcType=VARCHAR}
and fp.FINPROD_ID IN
#{finprodId,jdbcType=VARCHAR}
and tfpdl.TG_BUSI_TYPE IN
#{busiType,jdbcType=VARCHAR}
and tfpdl.SETTLE_METHOD = #{settleMethod,jdbcType=VARCHAR}
union all select '04' validStatus, tfpdl.TOTLE_TRADE_ID busiCode, tfpdl.TG_BUSI_TYPE paBussType, fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_NAME finprodMarketName, fp.VDATE vDateWhole, fp.MDATE mDateWhole, nvl(tfpdl.SHARE_AMT/10000,0) repNomCapi, fpd.REF_ENTITY refEntity, tfpdl.TG_BUSI_TYPE creditEvent, tfpdl.CREDIT_EVENT_HAPPENED_DATE creditEventHappenedDate, tfpdl.CREDIT_EVENT_RESOLVE_DATE creditEventResolveDate, tfpdl.SETTLE_METHOD settleMethod, tfpdl.DELIVER_BOND deliverBond, tfpdl.TRADE_DATE deliverDate from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL tfpdl left join FIN_PRODUCT fp on fp.FINPROD_ID = tfpdl.FINPROD_ID left join FIN_PRODUCT_ADD fpd on fpd.FINPROD_ID = tfpdl.FINPROD_ID where tfpdl.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F36} and tfpdl.IS_CANCEL = #{YES_OR_NO_N} and tfpdl.TRADE_STATUS = '01' and tfpdl.P_TOTLE_TRADE_ID is null
and tfpdl.TOTLE_TRADE_ID IN
#{busiCode,jdbcType=VARCHAR}
and fp.FINPROD_ID IN
#{finprodId,jdbcType=VARCHAR}
and tfpdl.TG_BUSI_TYPE IN
#{busiType,jdbcType=VARCHAR}
and tfpdl.SETTLE_METHOD = #{settleMethod,jdbcType=VARCHAR}
) T
and T.validStatus in
#{validStatus,jdbcType=VARCHAR}
order by T.FINPROD_MARKET_ID

select FINPROD_MARKET_ID id, NVL(FINPROD_ABBR, FINPROD_NAME) text from FIN_PRODUCT
and FINPROD_TYPE2 = #{finprodType2}
and (instr(FINPROD_MARKET_ID, #{search}) > 0 or instr(FINPROD_ID, #{search}) > 0 or instr(FINPROD_NAME, #{search}) > 0 or instr(FINPROD_ABBR, #{search}) > 0)

select nvl(p.AMOUNT, 0) / 10000
from PTL_SEC_POSITION p
         left join FIN_PRODUCT fp on fp.FINPROD_ID = p.FINPROD_ID
         left join STL_SEC_ACCT_INFO ssai on ssai.SEC_ACCT_ID = p.SEC_ACCT_ID
         left join STL_CAPACCT_INFO sci on ssai.REC_ACCT_ID = sci.ACCT_NO
         left join PTL_PORTFOLIO pp on p.PORTFOLIO_ID = pp.PORTFOLIO_ID
where p.PORTFOLIO_ID = #{portfolioId}
  and fp.FINPROD_MARKET_ID = #{finprodMarketId}
  and p.CDATE = #{tradeDate}
  and p.HODING_TYPE = '03'
